<?php
require_once '../includes/funcoes.php';exigir_admin();$id=(int)($_GET['id']??0);$p=['nome'=>'','descricao'=>'','preco'=>'','estoque'=>0,'categoria_id'=>'','marca_id'=>''];if($id){$s=$pdo->prepare("SELECT * FROM produtos WHERE id=?");$s->execute([$id]);$p=$s->fetch()?:$p;}
$cats=$pdo->query("SELECT * FROM categorias ORDER BY nome")->fetchAll();$marcas=$pdo->query("SELECT * FROM marcas ORDER BY nome")->fetchAll();$erro='';
if($_SERVER['REQUEST_METHOD']==='POST'){try{$data=[trim($_POST['nome']),trim($_POST['descricao']),(float)$_POST['preco'],(int)$_POST['estoque'],($_POST['categoria_id']?:null),($_POST['marca_id']?:null)];if($id){$data[]=$id;$pdo->prepare("UPDATE produtos SET nome=?,descricao=?,preco=?,estoque=?,categoria_id=?,marca_id=? WHERE id=?")->execute($data);}else{$pdo->prepare("INSERT INTO produtos(nome,descricao,preco,estoque,categoria_id,marca_id) VALUES(?,?,?,?,?,?)")->execute($data);}log_acao($id?'Produto editado':'Produto cadastrado');header('Location: produtos.php');exit;}catch(Throwable $e){$erro='Não foi possível salvar o produto.';}}
$titulo=$id?'Editar produto':'Novo produto';require '../includes/header.php';?>
<div class="admin-shell"><?php require '_menu.php';?><section><div class="panel"><h1><?=$id?'Editar':'Cadastrar'?> produto</h1><?php if($erro):?><div class="alert alert-danger"><?=$erro?></div><?php endif;?><form method="post"><label class="form-label">Nome</label><input class="form-control mb-3" name="nome" value="<?=e($p['nome'])?>" required><label class="form-label">Descrição</label><textarea class="form-control mb-3" name="descricao"><?=e($p['descricao'])?></textarea><div class="row"><div class="col-md-4"><label class="form-label">Preço</label><input class="form-control mb-3" type="number" step=".01" min="0" name="preco" value="<?=e($p['preco'])?>" required></div><div class="col-md-4"><label class="form-label">Estoque</label><input class="form-control mb-3" type="number" min="0" name="estoque" value="<?=e($p['estoque'])?>"></div><div class="col-md-4"><label class="form-label">Categoria</label><select class="form-select mb-3" name="categoria_id"><option value="">Sem categoria</option><?php foreach($cats as $c):?><option value="<?=$c['id']?>" <?=$p['categoria_id']==$c['id']?'selected':''?>><?=e($c['nome'])?></option><?php endforeach;?></select></div></div><label class="form-label">Marca</label><select class="form-select mb-3" name="marca_id"><option value="">Sem marca</option><?php foreach($marcas as $m):?><option value="<?=$m['id']?>" <?=$p['marca_id']==$m['id']?'selected':''?>><?=e($m['nome'])?></option><?php endforeach;?></select><button class="btn btn-lumia">Salvar</button> <a href="produtos.php" class="btn btn-outline-secondary">Cancelar</a></form></div></section></div><?php require '../includes/footer.php';?>
